import {battleCalculation} from './engine.mjs';
import {isMegaItem,resolveMegaForm} from './mega-classification.mjs';
/** Calculator UI controller. Battle formulas remain in engine.mjs. */
export function setupCalculator(ctx){
 const {$,stats,searchRows,row,team,makeSet,data,toast,esc,koreanType,strongestStatMove,damageScenarioResults,speedVariants}=ctx,ev=id=>$(id).value.split(',').map(x=>Number(x.trim()));
 const setOf=p=>team().find(x=>x?.name===p.name)||makeSet(p),options=(id,rows,current='',none='없음')=>$(id).innerHTML=`<option value="">${esc(none)}</option>`+rows.map(x=>{const n=Array.isArray(x)?x[0]:x.name||x;return `<option value="${esc(n)}"${n===current?' selected':''}>${esc(n)}</option>`}).join('');
 $('calcAtk').parentElement.insertAdjacentHTML('afterend','<label>공격 폼<select id="calcAtkMega"><option value="">일반폼</option></select></label>');
 $('calcDef').parentElement.insertAdjacentHTML('afterend','<label>수비 폼<select id="calcDefMega"><option value="">일반폼</option></select></label>');
 const megaChoice=(side,pokemon)=>{const select=$(`calc${side}Mega`);if(pokemon?.isMegaForm){select.innerHTML=`<option value="">직접 선택: ${esc(pokemon.name)}</option>`;select.disabled=true;return}const stones=(pokemon?.items||[]).filter(item=>isMegaItem(item.name,data.master)).map(item=>({item,resolved:resolveMegaForm(pokemon,item.name,data.master)})).filter(x=>x.resolved.ok||!x.resolved.reason.startsWith('선택한 스톤'));select.innerHTML='<option value="">일반폼</option>'+stones.map(({item,resolved})=>{const label=resolved.ok?`${resolved.formName} · ${item.name}`:`${item.name} · 대응 불명확 (계산 불가)`;return `<option value="${esc(item.name)}">${esc(label)}</option>`}).join('');select.disabled=!stones.length}
 const chosenForm=(side,pokemon)=>{const stone=$(`calc${side}Mega`).value;if(!stone)return {pokemon,form:null};const form=resolveMegaForm(pokemon,stone,data.master);if(!form.ok){toast(form.reason);return null}return {pokemon:{...pokemon,name:form.formName,types:form.types},form}}
 $('calcAtkMega').addEventListener('change',summaries);$('calcDefMega').addEventListener('change',summaries);
 function moves(){const p=row($('calcAtk').value.trim()),s=p&&setOf(p),names=s?.moves||p?.moves?.map(x=>x.name)||[],featured=names.map(n=>data.master.moves.find(m=>m[0]===n)).filter(m=>m&&m[3]!=='변화'&&Number(m[4])>0),seen=new Set(featured.map(m=>m[0])),others=data.master.moves.filter(m=>m[3]!=='변화'&&Number(m[4])>0&&!seen.has(m[0])),render=m=>`<option value="${esc(m[0])}">${esc(m[0])} · ${esc(koreanType[m[2]]||m[2])} · ${esc(m[3])} · 위력 ${m[4]}</option>`;$('calcMove').innerHTML=(featured.length?`<optgroup label="채용 기술">${featured.map(render).join('')}</optgroup>`:'')+`<optgroup label="전체 공격 기술">${others.map(render).join('')}</optgroup>`}
 function settings(){const a=row($('calcAtk').value.trim()),d=row($('calcDef').value.trim());if(!a||!d)return;const as=setOf(a),ds=setOf(d);$('calcAtkEvs').value=as.evs.join(',');$('calcDefEvs').value=ds.evs.join(',');options('calcAtkNature',a.natures,as.natures,'무보정');options('calcDefNature',d.natures,ds.natures,'무보정');options('calcAtkItem',a.items,as.items,'도구 없음');options('calcDefItem',d.items,ds.items,'도구 없음');options('calcAtkAbility',a.abilities,as.abilities,'특성 없음');options('calcDefAbility',d.abilities,ds.abilities,'특성 없음');megaChoice('Atk',a);megaChoice('Def',d);summaries()}
 function summaries(){for(const [side,id] of [['Atk','calcAtk'],['Def','calcDef']]){const p=row($(id).value.trim()),base=p&&data.master.pokemon.find(x=>x[0]===p.name)?.slice(3,9).map(Number),stone=$(`calc${side}Mega`).value,mega=stone&&p?resolveMegaForm(p,stone,data.master):null;$(`calc${side}Summary`).textContent=!base?'포켓몬을 선택하세요':mega?.ok?`${p.name} ${base.join('/')} → ${mega.formName} ${mega.formStats.join('/')} · ${mega.types.join('/')} · 메가 특성 미확인`:`${p.name} · ${base.join(' / ')}`}}
 function renderNames(){$('calcMons').innerHTML=searchRows().map(p=>`<option value="${esc(p.name)}">${p.isMegaForm?'메가폼':''}</option>`).join('');if(!row($('calcAtk').value))$('calcAtk').value=team().find(Boolean)?.name||stats()[0].name;if(!row($('calcDef').value))$('calcDef').value=stats()[1].name;moves();settings()}
 let lastForms=null;
 const formText=(base,choice)=>{const before=data.master.pokemon.find(row=>row[0]===base.name)?.slice(3,9).join('/');return choice.form?`${base.name} [${before}] → ${choice.form.formName} [${choice.form.formStats.join('/')}] · 타입 ${choice.form.types.join('/')} · ${choice.form.abilityReason}`:`${base.name} 일반폼 [${before}]`};
 new MutationObserver(()=>{if(!$('calcResult').firstChild||$('calcResult').querySelector('[data-form-result]')||!lastForms)return;const note=document.createElement('p');note.dataset.formResult='';note.className='leadnotice';note.textContent=`폼 적용 — 공격: ${formText(lastForms.baseAttacker,lastForms.af)} / 수비: ${formText(lastForms.baseDefender,lastForms.df)}`;$('calcResult').append(note)}).observe($('calcResult'),{childList:true});
 function get(){const baseAttacker=row($('calcAtk').value.trim()),baseDefender=row($('calcDef').value.trim()),move=data.master.moves.find(m=>m[0]===$('calcMove').value);if(!baseAttacker||!baseDefender)return toast('현재 챔피언스 목록에서 공격·방어 포켓몬을 선택해 주세요.');if(!move)return toast('계산할 공격 기술을 선택해 주세요.');const af=chosenForm('Atk',baseAttacker),df=chosenForm('Def',baseDefender);if(!af||!df)return null;const attacker=af.pokemon,defender=df.pokemon,set={...setOf(baseAttacker),evs:ev('calcAtkEvs'),natures:$('calcAtkNature').value,items:af.form||baseAttacker.isMegaForm?'':$('calcAtkItem').value,abilities:af.form||baseAttacker.isMegaForm?'':$('calcAtkAbility').value},calc=battleCalculation(attacker,defender,set,move,ev('calcDefEvs'),data.master,{defenderNature:$('calcDefNature').value,defenderHpPercent:$('calcHpPercent').value,hits:Number($('calcHits').value)});if(!calc){toast('EV(각 0~32·합계 66), 현재 체력(1~100%), 타수(1~10)를 확인해 주세요.');return null}lastForms={baseAttacker,baseDefender,af,df};return {attacker,defender,baseAttacker,baseDefender,attackerForm:af.form,defenderForm:df.form,move,set,calc}}
 const excluded=()=>['calcAtkRank','calcDefRank','calcWeather','calcField','calcForm','calcDefItem','calcDefAbility','calcWall','calcDouble'].map(id=>`${$(id).previousSibling.textContent.trim()}: ${$(id).value}`).filter(x=>!x.endsWith(': 0')&&!x.endsWith(': 없음')).join(' · ')||'추가 조건 없음';
 function run(){const x=get();if(!x)return;const {attacker,defender,move,calc}=x,bulk=[Math.round(calc.defenderStats[0]*calc.defenderStats[2]),Math.round(calc.defenderStats[0]*calc.defenderStats[4])],rolls=calc.damage.map((v,i)=>`${86+i}: ${v}`).join(' · ');$('calcResult').innerHTML=`<h3>${esc(attacker.name)} → ${esc(defender.name)}</h3><p><b>${esc(move[0])}</b> · ${esc(calc.type)} · ${esc(calc.category)} · 자속 ×${calc.stab} · 타입상성 ×${calc.typeMultiplier}</p><div class="calccards"><article><small>피해 범위</small><strong>${calc.result.min}~${calc.result.max} (${calc.result.minPct}~${calc.result.maxPct}%)</strong><b>${esc(calc.result.label)}</b></article><article><small>결정력 지수</small><strong>${calc.powerIndex.toLocaleString()}</strong><b>공격/특공 · 위력 · 자속 · 도구/특성</b></article><article><small>방어측 내구</small><strong>${bulk[0].toLocaleString()} / ${bulk[1].toLocaleString()}</strong><b>물리 / 특수</b></article><article><small>실능력치</small><strong>${calc.attackerStats.join(' / ')}</strong><b>공격측 H/A/B/C/D/S</b></article></div><p><small>난수 분포 (15개): ${rolls}</small></p><p class="leadnotice">적용: EV·성격·기술 위력·타입상성·자속·적응력·데이터에서 상시 확인 가능한 공격 도구/특성. 제외: ${esc(excluded())}. 명중·급소·상태·연속기·가변 위력도 제외합니다.</p>`}
 function runPowerSweep(){const x=get();if(!x)return;const best=strongestStatMove(x.attacker,x.defender,x.set,data.master);if(!best)return toast('계산 가능한 공격기를 찾지 못했습니다.');const lines=damageScenarioResults(x.attacker,x.defender,x.set,best.move,data.master).map(({label,calc})=>`<article><small>${esc(label)}</small><strong>${calc.result.minPct}~${calc.result.maxPct}%</strong><b>${esc(calc.result.label)} · ${calc.result.min}~${calc.result.max}</b></article>`).join('');$('calcResult').innerHTML=`<h3>${esc(x.attacker.name)} → ${esc(x.defender.name)} 내구별 피해</h3><p><b>${esc(best.move[0])}</b> · 채용률 ${best.rate}% · 방어측 성격은 이 일괄 표에서 무보정입니다.</p><div class="calccards sweepcards">${lines}</div><p class="leadnotice">H/B/D EV별 기본 비교입니다. 상세 계산의 방어 성격 및 미확인 전장 조건은 이 표에 적용하지 않습니다.</p>`}
 function runSpeedCompare(){const x=get();if(!x)return;const {attacker,defender,calc}=x,as=calc.speed,ds=calc.defenderStats[5],mark=as===ds?'＝':as>ds?'＞':'＜',win=as===ds?'동속':as>ds?attacker.name:defender.name,tiers=speedVariants(attacker,data.master)||[];$('calcResult').innerHTML=`<h3>${esc(attacker.name)} ↔ ${esc(defender.name)} 스피드 비교</h3><div class="calccards speedcards"><article><small>현재 세팅</small><strong>${as} ${mark} ${ds}</strong><b>${esc(win)}${win==='동속'?'':'이 먼저 행동'}</b></article>${tiers.map(t=>`<article><small>${esc(t.label)}</small><strong>${t.value}</strong><b>${t.value>ds?'방어측보다 빠름':t.value===ds?'동속':'방어측보다 느림'}</b></article>`).join('')}</div><p class="leadnotice">현재 공격측은 선택 EV·성격과 구애스카프만, 방어측은 선택 EV·성격만 반영합니다. 순풍·마비·랭크·필드·특성 등 확인되지 않은 스피드 규칙은 제외합니다.</p>`}
 $('calculators').querySelector('.sectionhead').insertAdjacentHTML('afterend','<div class="calc-toolbar"><button id="calcSwap" type="button">공격 ↔ 수비 교체</button><span>모든 공격 기술 선택 가능 · 채용 기술 우선 표시</span></div><div class="calc-summary"><article><small>공격측 종족값 H/A/B/C/D/S</small><strong id="calcAtkSummary">포켓몬을 선택하세요</strong></article><article><small>수비측 종족값 H/A/B/C/D/S</small><strong id="calcDefSummary">포켓몬을 선택하세요</strong></article></div>');$('calcMove').parentElement.insertAdjacentHTML('afterend','<label>현재 체력 (%)<input id="calcHpPercent" type="number" min="1" max="100" value="100"></label><label>타수<input id="calcHits" type="number" min="1" max="10" value="1"></label>');$('calcAtk').addEventListener('change',()=>{moves();settings()});$('calcDef').addEventListener('change',settings);$('calcSwap').onclick=()=>{const a=$('calcAtk').value;$('calcAtk').value=$('calcDef').value;$('calcDef').value=a;moves();settings()};$('calcRun').onclick=run;$('calcPowerSweep').onclick=runPowerSweep;$('calcSpeedCompare').onclick=runSpeedCompare;return {renderNames,moves,renderMoves:moves};
}
